page_settings.custom_css:
/* NOVELLE Minimal Editorial Product Card */
.elementor-element-{{ID}} {
    transition: transform 0.3s ease;
}
.elementor-element-{{ID}} .novelle-img-wrap {
    position: relative;
    overflow: hidden;
    aspect-ratio: 3 / 4;
}
.elementor-element-{{ID}} .novelle-img-wrap img {
    transition: transform 0.45s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    width: 100%;
    height: 100%;
    object-fit: cover;
}
.elementor-element-{{ID}}:hover .novelle-img-wrap img {
    transform: scale(1.045);
}
.elementor-element-{{ID}} .novelle-wishlist {
    position: absolute;
    top: 8px;
    right: 8px;
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.85);
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.25s ease;
    backdrop-filter: blur(4px);
    z-index: 2;
}
.elementor-element-{{ID}} .novelle-wishlist:hover {
    background: #FFFFFF;
    color: #B23B3B;
    transform: scale(1.12);
}
.elementor-element-{{ID}} .novelle-add-to-cart a,
.elementor-element-{{ID}} .novelle-add-to-cart button {
    background-color: #665549 !important;
    color: #FFFFFF !important;
    border-radius: 0px !important;
    border: 1px solid #665549 !important;
    font-size: 11px !important;
    letter-spacing: 2px !important;
    text-transform: uppercase !important;
    width: 100% !important;
    transition: all 0.25s ease !important;
    min-height: 38px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
}
.elementor-element-{{ID}} .novelle-add-to-cart a:hover,
.elementor-element-{{ID}} .novelle-add-to-cart button:hover {
    background-color: #554438 !important;
    border-color: #554438 !important;
    transform: translateY(-1px);
}
